import{_ as t,o as e,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const r=JSON.parse('{"title":"The plan format","description":"","frontmatter":{},"headers":[],"relativePath":"docs/plan-format.md","filePath":"docs/plan-format.md","lastUpdated":null}'),u={name:"docs/plan-format.md"};function s(c,o,d,i,q,l){return e(),a("div",null,[...o[0]||(o[0]=[n(`<h1 id="the-plan-format" tabindex="-1">The plan format <a class="header-anchor" href="#the-plan-format" aria-label="Permalink to &quot;The plan format&quot;">​</a></h1><p><code>linnet plan [--root &lt;Block&gt;] &lt;file&gt;</code> prints one JSON document that a materializer consumes. Version 1:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>{ &quot;version&quot;: 1,</span></span>
<span class="line"><span>  &quot;module&quot;:    &quot;a.b.c&quot;,</span></span>
<span class="line"><span>  &quot;root&quot;:      { &quot;name&quot;, &quot;generics&quot;: [generic], &quot;constraints&quot;: [constraint] },</span></span>
<span class="line"><span>  &quot;manifest&quot;:  [ { &quot;path&quot;, &quot;kind&quot;: &quot;param&quot; | &quot;buffer&quot; | &quot;state&quot;, &quot;dtype&quot;, &quot;shape&quot;: [unit],</span></span>
<span class="line"><span>                   &quot;repeat&quot;: [dim], &quot;optional&quot; } ],</span></span>
<span class="line"><span>  &quot;blocks&quot;:    { &lt;name&gt;: { &quot;module&quot;, &quot;pub&quot;, &quot;generics&quot;: [generic], &quot;constraints&quot;: [constraint],</span></span>
<span class="line"><span>                           &quot;members&quot;: [ { &quot;name&quot;, &quot;kind&quot;: &quot;param&quot; | &quot;buffer&quot; | &quot;state&quot; | &quot;sub&quot;,</span></span>
<span class="line"><span>                                          &quot;type&quot;: type } ] } },</span></span>
<span class="line"><span>  &quot;functions&quot;: [ { &quot;name&quot;, &quot;kind&quot;: &quot;fn&quot; | &quot;op&quot; | &quot;entry&quot;, &quot;block&quot;: name | null, &quot;pub&quot;,</span></span>
<span class="line"><span>                   &quot;generics&quot;: [generic], &quot;constraints&quot;: [constraint],</span></span>
<span class="line"><span>                   &quot;results&quot;: [type], &quot;states&quot;: [path], &quot;body&quot;: region } ],</span></span>
<span class="line"><span>  &quot;constants&quot;: [ { &quot;name&quot;, &quot;pub&quot;, &quot;type&quot;: type, &quot;contextual&quot;, &quot;body&quot;: region } ] }</span></span></code></pre></div><ul><li><p><code>states</code> lists the <code>state</code> members a function reads or writes, directly or through the methods it calls, as paths relative to its block (<code>[*]</code> stands for every element of a sub array). In the body they are the operations <code>state.read</code> (operand: the block value; attribute <code>name</code>) and <code>state.write</code> (operands: the block value and the new value; no result), ordered within their region.</p></li><li><p><code>constants</code> are module-level <code>const</code> items with their initializer as a region yielding one value; uses are already inlined into the functions. <code>contextual</code> marks a constant declared without a type (a compile-time integer or a float literal that adopts its dtype where it is used).</p></li><li><p><code>module</code> is the path of the root file&#39;s module; function names are <code>module.path::name</code> (<code>module.path::Block.method</code> for methods).</p></li><li><p><code>generic</code>: <code>{ &quot;name&quot;, &quot;kind&quot;: &quot;dim&quot; | &quot;shape&quot; | &quot;dtype&quot;, &quot;sym&quot; | &quot;var&quot;, &quot;default&quot;? }</code>; a dtype generic also has <code>&quot;class&quot;: &quot;any&quot; | &quot;numeric&quot; | &quot;integer&quot; | &quot;float&quot;</code>. Symbols and dtype variables are numbered by the compiler; a call&#39;s <code>substitution</code> maps the callee&#39;s numbers to expressions in the caller.</p></li><li><p><code>dim</code>: an integer, <code>{ &quot;sym&quot;, &quot;name&quot; }</code>, <code>{ &quot;packsize&quot;, &quot;name&quot; }</code>, or <code>{ &quot;op&quot;: &quot;add&quot; | &quot;mul&quot; | &quot;floordiv&quot; | &quot;mod&quot; | &quot;min&quot; | &quot;max&quot;, &quot;args&quot;: [dim] }</code>.</p></li><li><p><code>unit</code> (one element of a shape): a <code>dim</code>, or <code>{ &quot;pack&quot;, &quot;name&quot; }</code> standing for every axis of a shape pack.</p></li><li><p><code>type</code>: <code>{ &quot;kind&quot;: &quot;scalar&quot;, &quot;dtype&quot; }</code>, <code>{ &quot;kind&quot;: &quot;tensor&quot;, &quot;shape&quot;: [unit], &quot;dtype&quot; }</code>, <code>tuple</code>, <code>optional</code>, <code>array</code>, <code>block</code> / <code>struct</code> / <code>enum</code> with <code>name</code>, <code>module</code>, and <code>args</code>, <code>shape</code>, <code>unit</code>. A dtype is a name such as <code>&quot;bf16&quot;</code> or <code>{ &quot;var&quot;, &quot;name&quot; }</code>.</p></li><li><p><code>region</code>: <code>{ &quot;args&quot;: [value], &quot;ops&quot;: [op] }</code> with one block per region; <code>value</code> is <code>{ &quot;id&quot;, &quot;name&quot;, &quot;type&quot; }</code>.</p></li><li><p><code>op</code>: <code>{ &quot;kind&quot;, &quot;operands&quot;: [id], &quot;results&quot;: [value], &quot;attrs&quot;: {...}, &quot;regions&quot;: [region] }</code>. Kinds and attributes follow the Core IR operations (<code>include/linnet/ir/ir.hpp</code>); <code>comprehension</code> and <code>reduce</code> list their <code>indices</code> with domains, <code>slice</code> lists per-axis <code>start</code>/<code>stop</code>/<code>step</code>/<code>squeeze</code> or <code>whole</code> (a shape pack), and calls carry <code>callee</code>, <code>substitution</code>, and <code>generics</code> (the same bindings as generic values, in the callee&#39;s declaration order, so that a reader without the callee can still spell the call).</p></li></ul><p>Dimensions stay symbolic. The materializer binds the root block&#39;s generics, then each block instance&#39;s, then an entry&#39;s from its inputs, and evaluates the expressions. The plan contains no tensor data.</p>`,5)])])}const m=t(u,[["render",s]]);export{r as __pageData,m as default};
